package com.dbtraining.reconx.kafka;
import com.dbtraining.reconx.dto.TradeEvent; import com.dbtraining.reconx.repository.DlqMessageRepository; import com.dbtraining.reconx.repository.entity.DlqMessage; import com.fasterxml.jackson.databind.ObjectMapper; import org.apache.kafka.clients.consumer.ConsumerRecord; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import java.time.Instant;
@Component public class DlqConsumer { private final DlqMessageRepository repo; private final ObjectMapper json; public DlqConsumer(DlqMessageRepository repo,ObjectMapper json){this.repo=repo;this.json=json;} @KafkaListener(topics="trade-events-dlq",groupId="dlq-monitor") public void consume(ConsumerRecord<String,TradeEvent> record){try{var e=record.value();repo.save(new DlqMessage(e.eventId().toString(),e.tradeRef(),record.topic().replace("-dlq",""),record.partition(),record.offset(),json.writeValueAsString(e),"Kafka listener failure",Instant.now()));}catch(Exception ex){throw new IllegalStateException(ex);}} }
